I'll analyze how kanban is currently used in the components and create a new kanban store with proper project-scoped operations.

## Analysis of Current Usage

From the components, I can see:

1. **Kanban structure**: `project.$state.kanban = { boards: { [boardTitle]: { columns, tasks, ... } } }`
2. **Current operations**: 
   - `this.$storex.projects.loadKanban({ project })`
   - `this.$storex.projects.saveKanban({ project })`
   - `this.$projects.setActiveBoard(board)`
   - `this.$projects.activeBoard` (computed)
3. **Board operations**: create, update, delete, rename
4. **Column operations**: add, edit, delete
5. **Task operations**: move between columns, create, delete

Now I'll create the kanban store:

```js /home/codx-junior-projects/codx-junior/client/src/stores/kanban.js
import { defineStore } from 'pinia'
import { v4 as uuidv4 } from 'uuid'

export const useKanbanStore = defineStore('kanban', {
  state: () => ({
    // Map of projectId -> activeBoard
    activeBoardByProject: {},
    // Map of projectId -> kanban state
    kanbanByProject: {}
  }),

  getters: {
    /**
     * Get kanban state for a project
     */
    getProjectKanban: (state) => (projectId) => {
      return state.kanbanByProject[projectId] || { boards: {} }
    },

    /**
     * Get active board ID for a project
     */
    getActiveBoard: (state) => (projectId) => {
      return state.activeBoardByProject[projectId] || null
    },

    /**
     * Get specific board from project kanban
     */
    getBoard: (state) => (projectId, boardTitle) => {
      const kanban = state.kanbanByProject[projectId] || { boards: {} }
      return kanban.boards[boardTitle] || null
    },

    /**
     * Get all boards for a project (with id/title)
     */
    getBoardsList: (state) => (projectId) => {
      const kanban = state.kanbanByProject[projectId] || { boards: {} }
      return Object.entries(kanban.boards).map(([title, data]) => ({
        title,
        id: title,
        ...data
      }))
    },

    /**
     * Get parent boards (no parent_id)
     */
    getParentBoards: (state) => (projectId) => {
      const kanban = state.kanbanByProject[projectId] || { boards: {} }
      return Object.entries(kanban.boards)
        .filter(([_, board]) => !board.parent_id)
        .map(([title, data]) => ({ title, id: title, ...data }))
    },

    /**
     * Get child boards for a specific board
     */
    getChildBoards: (state) => (projectId, boardId) => {
      const kanban = state.kanbanByProject[projectId] || { boards: {} }
      return Object.entries(kanban.boards)
        .filter(([_, board]) => board.parent_id === boardId)
        .map(([title, data]) => ({ title, id: title, ...data }))
    },

    /**
     * Get all descendants of a board (recursive)
     */
    getDescendantBoards: (state) => (projectId, boardId) => {
      const kanban = state.kanbanByProject[projectId] || { boards: {} }
      const descendants = []
      const collect = (parentId) => {
        Object.entries(kanban.boards).forEach(([title, board]) => {
          if (board.parent_id === parentId) {
            descendants.push({ title, id: title, ...board })
            collect(title)
          }
        })
      }
      collect(boardId)
      return descendants
    },

    /**
     * Get columns for a board
     */
    getBoardColumns: (state) => (projectId, boardTitle) => {
      const board = state.kanbanByProject[projectId]?.boards[boardTitle]
      return board?.columns || []
    },

    /**
     * Get all column titles for a board (from columns + task columns)
     */
    getColumnTitles: (state) => (projectId, boardTitle) => {
      const board = state.kanbanByProject[projectId]?.boards[boardTitle]
      return board?.columns?.map(c => c.title) || []
    }
  },

  actions: {
    /**
     * Initialize kanban for a project
     */
    initProjectKanban(projectId, kanbanState = { boards: {} }) {
      this.kanbanByProject[projectId] = kanbanState
      if (!this.activeBoardByProject[projectId]) {
        const firstBoard = Object.keys(kanbanState.boards)[0]
        this.activeBoardByProject[projectId] = firstBoard || null
      }
    },

    /**
     * Set active board for a project
     */
    setActiveBoard(projectId, boardTitle) {
      this.activeBoardByProject[projectId] = boardTitle
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (board) {
        // Mark as active
        Object.values(this.kanbanByProject[projectId].boards).forEach(b => {
          b.active = b === board
        })
        board.last_update = new Date().toISOString()
      }
    },

    /**
     * Create a new board
     */
    createBoard(projectId, { title, description = '', background = '', parentId = null }) {
      const kanban = this.kanbanByProject[projectId]
      if (!kanban) {
        console.error(`Kanban not initialized for project ${projectId}`)
        return null
      }

      if (kanban.boards[title]) {
        console.warn(`Board "${title}" already exists`)
        return null
      }

      const newBoard = {
        title,
        description,
        background,
        parent_id: parentId,
        columns: [],
        last_update: new Date().toISOString(),
        created_at: new Date().toISOString(),
        active: false,
        bookmark: false
      }

      kanban.boards[title] = newBoard
      return newBoard
    },

    /**
     * Update board properties
     */
    updateBoard(projectId, boardTitle, updates) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) {
        console.error(`Board "${boardTitle}" not found`)
        return null
      }

      Object.assign(board, updates, { last_update: new Date().toISOString() })
      return board
    },

    /**
     * Rename a board
     */
    renameBoard(projectId, oldTitle, newTitle) {
      const kanban = this.kanbanByProject[projectId]
      if (!kanban) return null

      const board = kanban.boards[oldTitle]
      if (!board) {
        console.error(`Board "${oldTitle}" not found`)
        return null
      }

      if (kanban.boards[newTitle]) {
        console.warn(`Board "${newTitle}" already exists`)
        return null
      }

      // Update children's parent_id
      Object.values(kanban.boards).forEach(b => {
        if (b.parent_id === oldTitle) {
          b.parent_id = newTitle
        }
      })

      // Move board
      board.title = newTitle
      kanban.boards[newTitle] = board
      delete kanban.boards[oldTitle]

      // Update active board if needed
      if (this.activeBoardByProject[projectId] === oldTitle) {
        this.activeBoardByProject[projectId] = newTitle
      }

      return board
    },

    /**
     * Delete a board and its children
     */
    deleteBoard(projectId, boardTitle) {
      const kanban = this.kanbanByProject[projectId]
      if (!kanban) return false

      if (!kanban.boards[boardTitle]) {
        console.error(`Board "${boardTitle}" not found`)
        return false
      }

      // Recursively delete children
      const children = Object.keys(kanban.boards).filter(
        title => kanban.boards[title].parent_id === boardTitle
      )
      children.forEach(childTitle => this.deleteBoard(projectId, childTitle))

      // Delete board
      delete kanban.boards[boardTitle]

      // Reset active board if needed
      if (this.activeBoardByProject[projectId] === boardTitle) {
        const remaining = Object.keys(kanban.boards)[0]
        this.activeBoardByProject[projectId] = remaining || null
      }

      return true
    },

    /**
     * Toggle board bookmark
     */
    toggleBookmark(projectId, boardTitle) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (board) {
        board.bookmark = !board.bookmark
        board.last_update = new Date().toISOString()
      }
      return board
    },

    /**
     * Add a column to a board
     */
    addColumn(projectId, boardTitle, { title, color = null, projectId: colProjectId = null }) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) {
        console.error(`Board "${boardTitle}" not found`)
        return null
      }

      if (!board.columns) board.columns = []

      // Check for duplicate
      if (board.columns.some(c => c.title === title)) {
        console.warn(`Column "${title}" already exists`)
        return null
      }

      const newColumn = {
        id: uuidv4(),
        title,
        color,
        project_id: colProjectId,
        showSubTasks: false,
        chats: []
      }

      board.columns.push(newColumn)
      board.last_update = new Date().toISOString()

      return newColumn
    },

    /**
     * Update column properties
     */
    updateColumn(projectId, boardTitle, columnId, updates) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) return null

      const column = board.columns?.find(c => c.id === columnId || c.title === updates.title)
      if (!column) {
        console.error(`Column not found`)
        return null
      }

      Object.assign(column, updates)
      board.last_update = new Date().toISOString()

      return column
    },

    /**
     * Delete a column from a board
     */
    deleteColumn(projectId, boardTitle, columnTitle) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) return false

      const initialLength = board.columns?.length || 0
      board.columns = board.columns?.filter(c => c.title !== columnTitle) || []

      if (board.columns.length < initialLength) {
        board.last_update = new Date().toISOString()
        return true
      }

      return false
    },

    /**
     * Reorder columns
     */
    reorderColumns(projectId, boardTitle, columnOrder) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board || !board.columns) return false

      const newColumns = []
      columnOrder.forEach(title => {
        const col = board.columns.find(c => c.title === title)
        if (col) newColumns.push(col)
      })

      board.columns = newColumns
      board.last_update = new Date().toISOString()

      return true
    },

    /**
     * Add file to board
     */
    addFilesToBoard(projectId, boardTitle, filePaths) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) return null

      if (!board.file_list) board.file_list = []
      board.file_list = [...new Set([...board.file_list, ...filePaths])]
      board.last_update = new Date().toISOString()

      return board
    },

    /**
     * Get all boards as flat list with hierarchy info
     */
    getAllBoardsFlat(projectId) {
      const kanban = this.kanbanByProject[projectId] || { boards: {} }
      return Object.entries(kanban.boards).map(([title, board]) => ({
        title,
        id: title,
        ...board,
        depth: this.calculateBoardDepth(projectId, title)
      }))
    },

    /**
     * Calculate board depth in hierarchy
     */
    calculateBoardDepth(projectId, boardTitle, visited = new Set()) {
      if (visited.has(boardTitle)) return 0
      visited.add(boardTitle)

      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board?.parent_id) return 0

      return 1 + this.calculateBoardDepth(projectId, board.parent_id, visited)
    }
  }
})
