    renameBoard(projectId, oldTitle, newTitle) {
      const kanban = this.kanbanByProject[projectId]
      if (!kanban) return null

      const board = kanban.boards[oldTitle]
      if (!board) {
        console.error(`Board "${oldTitle}" not found`)
        return null
      }

      if (kanban.boards[newTitle]) {
        console.warn(`Board "${newTitle}" already exists`)
        return null
      }

      // Update children's parent_id
      Object.values(kanban.boards).forEach(b => {
        if (b.parent_id === oldTitle) {
          b.parent_id = newTitle
        }
      })

      // Move board
      board.title = newTitle
      kanban.boards[newTitle] = board
      delete kanban.boards[oldTitle]

      // Update active board if needed
      if (this.activeBoardByProject[projectId] === oldTitle) {
        this.activeBoardByProject[projectId] = newTitle
      }

      return board
    },

    /**
     * Delete a board and its children
     */
    deleteBoard(projectId, boardTitle) {
      const kanban = this.kanbanByProject[projectId]
      if (!kanban) return false

      if (!kanban.boards[boardTitle]) {
        console.error(`Board "${boardTitle}" not found`)
        return false
      }

      // Recursively delete children
      const children = Object.keys(kanban.boards).filter(
        title => kanban.boards[title].parent_id === boardTitle
      )
      children.forEach(childTitle => this.deleteBoard(projectId, childTitle))

      // Delete board
      delete kanban.boards[boardTitle]

      // Reset active board if needed
      if (this.activeBoardByProject[projectId] === boardTitle) {
        const remaining = Object.keys(kanban.boards)[0]
        this.activeBoardByProject[projectId] = remaining || null
      }

      return true
    },

    /**
     * Toggle board bookmark
     */
    toggleBookmark(projectId, boardTitle) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (board) {
        board.bookmark = !board.bookmark
        board.last_update = new Date().toISOString()
      }
      return board
    },

    /**
     * Add a column to a board
     */
    addColumn(projectId, boardTitle, { title, color = null, projectId: colProjectId = null }) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) {
        console.error(`Board "${boardTitle}" not found`)
        return null
      }

      if (!board.columns) board.columns = []

      // Check for duplicate
      if (board.columns.some(c => c.title === title)) {
        console.warn(`Column "${title}" already exists`)
        return null
      }

      const newColumn = {
        id: uuidv4(),
        title,
        color,
        project_id: colProjectId,
        showSubTasks: false,
        chats: []
      }

      board.columns.push(newColumn)
      board.last_update = new Date().toISOString()

      return newColumn
    },

    /**
     * Update column properties
     */
    updateColumn(projectId, boardTitle, columnId, updates) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) return null

      const column = board.columns?.find(c => c.id === columnId || c.title === updates.title)
      if (!column) {
        console.error(`Column not found`)
        return null
      }

      Object.assign(column, updates)
      board.last_update = new Date().toISOString()

      return column
    },

    /**
     * Delete a column from a board
     */
    deleteColumn(projectId, boardTitle, columnTitle) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) return false

      const initialLength = board.columns?.length || 0
      board.columns = board.columns?.filter(c => c.title !== columnTitle) || []

      if (board.columns.length < initialLength) {
        board.last_update = new Date().toISOString()
        return true
      }

      return false
    },

    /**
     * Reorder columns
     */
    reorderColumns(projectId, boardTitle, columnOrder) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board || !board.columns) return false

      const newColumns = []
      columnOrder.forEach(title => {
        const col = board.columns.find(c => c.title === title)
        if (col) newColumns.push(col)
      })

      board.columns = newColumns
      board.last_update = new Date().toISOString()

      return true
    },

    /**
     * Add file to board
     */
    addFilesToBoard(projectId, boardTitle, filePaths) {
      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board) return null

      if (!board.file_list) board.file_list = []
      board.file_list = [...new Set([...board.file_list, ...filePaths])]
      board.last_update = new Date().toISOString()

      return board
    },

    /**
     * Get all boards as flat list with hierarchy info
     */
    getAllBoardsFlat(projectId) {
      const kanban = this.kanbanByProject[projectId] || { boards: {} }
      return Object.entries(kanban.boards).map(([title, board]) => ({
        title,
        id: title,
        ...board,
        depth: this.calculateBoardDepth(projectId, title)
      }))
    },

    /**
     * Calculate board depth in hierarchy
     */
    calculateBoardDepth(projectId, boardTitle, visited = new Set()) {
      if (visited.has(boardTitle)) return 0
      visited.add(boardTitle)

      const board = this.kanbanByProject[projectId]?.boards[boardTitle]
      if (!board?.parent_id) return 0

      return 1 + this.calculateBoardDepth(projectId, board.parent_id, visited)
    }
  }
})

import Service from "./service"
import { useKanbanStore } from '@/stores/kanban'

export class ProjectService extends Service {
  async cloneProject(projectPath) {
    if (projectPath.includes("github.com") &&
        projectPath.includes("/issues/")) {
        projectPath = projectPath.split("/issues/")[0]
    } 
    await this.$projects.createNewProject(projectPath)
  }

  async watch(watching) {
    this.$project.$api.projects.watch(watching)
  }

  async openUserChat(user) {
    const chat = this.$projects.allChats.find(({ column, board, name }) => 
      column === "chats" && board === "chats" && name === user.username
    ) ||  await this.$chats.createNewChat({
      board: "chats",
      column: "chats",
      name: user.username,
      mode: 'channel'
    })
    this.$projects.setActiveChat(chat)

    if (this.$ui.activeTab !== 'tasks') {
      this.$ui.setActiveTab('tasks')
    }
  }

  findParentProject(project) {
    const  { allProjects } = this.$storex.api
    return allProjects.find(p =>
      p.abs_project_path !== project.abs_project_path && 
      project.abs_project_path.startsWith(p.abs_project_path))
  }

  findChildProject(project) {
    const  { allProjects } = this.$storex.api
    return allProjects.filter(p => 
      p.abs_project_path !== project.abs_project_path && 
      p.abs_project_path.startsWith(project.abs_project_path))
  }

  findProjectDependencies(project) {
    const  { allProjects } = this.$storex.api
    const { project_dependencies } = project
    return `${project_dependencies}`.split(",").map(dep => 
      allProjects.find(({ project_name }) => project_name === dep.trim()))
                          .filter(p => !!p)
  }

  async mentionList(project, profiles) {
    const parentProject = this.findParentProject(project)
    const childProjects = this.findChildProject(project)
    const projectDependencies = this.findProjectDependencies(project)
    return [
      ...this.$storex.api.userNetwork.map(user => ({ 
        name: user.username,
        user,
        tooltip: `User @${user.username}` 
      })),
      ...profiles.map(profile => ({ 
          name: profile.name,
          profile,
          tooltip: profile.description 
        })),
      ...[
        project,
        parentProject,
        ...childProjects,
        ...projectDependencies,
      ]
        .filter(project => project)
        .map(project => ({ name: project.project_name, project, tooltip: `Search in project ${project.project_name}` })),
      ...[
        ...project.knowledge?.files || [],
        ...project.knowledge?.pending_files || []
      ]
        .map(file => ({ file,
                        name: file.split('/').reverse()[0],
                        filePath: file.split('/').reverse().slice(0, 3).reverse().join('/')
                      }))
        .map(({ file, name, filePath }) => ({ 
                        name, 
                        file, 
                        searchIndex: filePath,
                        tooltip: `Use file ${filePath}`
                      })),
    ].map(m => ({ 
      ...m,
      searchIndex: m.searchIndex || m.name.toLowerCase(),
      mention: encodeURIComponent(m.name)
    }))
  }

  async loadProjectContext(project) {
    const { project_name, codx_path } = project
    if ( project_name && !codx_path ) {
      project = this.$storex.projects.allProjects.find(p => p.project_name === project_name)
    }

    const API = await this.$storex.api.project(project)
    const [models, profiles ] = await Promise.all([
      API.projects.ai.models.list(),
      API.profiles.list(),
    ])
    const mentionList = await this.mentionList(project, profiles)
    return {
      ...project,
      api: API,
      models,
      profiles,
      mentionList
    }
  }

  /**
   * Load kanban for a project
   */
  async loadKanban(project) {
    const kanbanStore = useKanbanStore()
    const kanban = project.$state?.kanban || { boards: {} }
    kanbanStore.initProjectKanban(project.project_id, kanban)
  }

  /**
   * Save kanban for a project
   */
  async saveKanban(project) {
    const kanbanStore = useKanbanStore()
    const kanban = kanbanStore.getProjectKanban(project.project_id)
    if (project.$state) {
      project.$state.kanban = kanban
    }
    // Persist to backend if needed
    await this.$storex.projects.saveProject({ project })
  }

  /**
   * Set active board for project
   */
  setActiveBoard(project, boardTitle) {
    const kanbanStore = useKanbanStore()
    kanbanStore.setActiveBoard(project.project_id, boardTitle)
  }

  /**
   * Get active board for project
   */
  getActiveBoard(project) {
    const kanbanStore = useKanbanStore()
    return kanbanStore.getActiveBoard(project.project_id)
  }
}

import { computed } from 'vue'
import { useKanbanStore } from '@/stores/kanban'

/**
 * Composable for working with project kanban
 * Usage: const { kanban, activeBoard, ... } = useProjectKanban(project)
 */
export function useProjectKanban(project) {
  const kanbanStore = useKanbanStore()

  const projectId = computed(() => project?.project_id)

  const kanban = computed(() => 
    kanbanStore.getProjectKanban(projectId.value)
  )

  const activeBoard = computed(() =>
    kanbanStore.getActiveBoard(projectId.value)
  )

  const boards = computed(() =>
    kanbanStore.getBoardsList(projectId.value)
  )

  const parentBoards = computed(() =>
    kanbanStore.getParentBoards(projectId.value)
  )

  const currentBoard = computed(() =>
    kanbanStore.getBoard(projectId.value, activeBoard.value)
  )

  const childBoards = computed(() =>
    kanbanStore.getChildBoards(projectId.value, activeBoard.value)
  )

  const currentBoardColumns = computed(() =>
    kanbanStore.getBoardColumns(projectId.value, activeBoard.value)
  )

  // Actions
  const setActiveBoard = (boardTitle) => {
    kanbanStore.setActiveBoard(projectId.value, boardTitle)
  }

  const createBoard = (params) => {
    return kanbanStore.createBoard(projectId.value, params)
  }

  const updateBoard = (boardTitle, updates) => {
    return kanbanStore.updateBoard(projectId.value, boardTitle, updates)
  }

  const renameBoard = (oldTitle, newTitle) => {
    return kanbanStore.renameBoard(projectId.value, oldTitle, newTitle)
  }

  const deleteBoard = (boardTitle) => {
    return kanbanStore.deleteBoard(projectId.value, boardTitle)
  }

  const toggleBookmark = (boardTitle) => {
    return kanbanStore.toggleBookmark(projectId.value, boardTitle)
  }

  const addColumn = (boardTitle, params) => {
    return kanbanStore.addColumn(projectId.value, boardTitle, params)
  }

  const updateColumn = (boardTitle, columnId, updates) => {
    return kanbanStore.updateColumn(projectId.value, boardTitle, columnId, updates)
  }

  const deleteColumn = (boardTitle, columnTitle) => {
    return kanbanStore.deleteColumn(projectId.value, boardTitle, columnTitle)
  }

  const reorderColumns = (boardTitle, columnOrder) => {
    return kanbanStore.reorderColumns(projectId.value, boardTitle, columnOrder)
  }

  const addFilesToBoard = (boardTitle, filePaths) => {
    return kanbanStore.addFilesToBoard(projectId.value, boardTitle, filePaths)
  }

  return {
    // Computed
    kanban,
    activeBoard,
    boards,
    parentBoards,
    currentBoard,
    childBoards,
    currentBoardColumns,
    // Actions
    setActiveBoard,
    createBoard,
    updateBoard,
    renameBoard,
    deleteBoard,
    toggleBookmark,
    addColumn,
    updateColumn,
    deleteColumn,
    reorderColumns,
    addFilesToBoard
  }
}
